import{_ as t,o as a,c as s,a3 as n}from"./chunks/framework.B02wg2PO.js";const u=JSON.parse('{"title":"Installing from the Marketplace","description":"","frontmatter":{},"headers":[],"relativePath":"guides/marketplace.md","filePath":"guides/marketplace.md"}'),o={name:"guides/marketplace.md"};function r(i,e,l,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="installing-from-the-marketplace" tabindex="-1">Installing from the Marketplace <a class="header-anchor" href="#installing-from-the-marketplace" aria-label="Permalink to &quot;Installing from the Marketplace&quot;">​</a></h1><p>The Marketplace is Saidi&#39;s catalog of <strong>MCP servers</strong> and <strong>skills</strong> you can attach to an agent. It aggregates several upstream sources into one searchable list, caches them, and materialises the chosen entry into the target agent&#39;s configuration.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>Provides</th></tr></thead><tbody><tr><td>MCP Registry</td><td>Published MCP servers</td></tr><tr><td>GitHub</td><td>Servers and skills resolved straight from repos</td></tr><tr><td>Glama</td><td>Indexed MCP server catalog</td></tr><tr><td>Skills marketplace</td><td>Reusable skill definitions</td></tr><tr><td>HTTP</td><td>Any catalog served as JSON at a URL</td></tr></tbody></table><p>Results are normalised into one entry shape and cached, so browsing does not hammer upstream on every keystroke. <code>saidi-marketplace</code> runs the catalog service standalone from <strong>Settings → Connections</strong> if you want to point at your own.</p><h2 id="install-an-mcp-server" tabindex="-1">Install an MCP server <a class="header-anchor" href="#install-an-mcp-server" aria-label="Permalink to &quot;Install an MCP server&quot;">​</a></h2><p>From the UI: <strong>Marketplace → find the server → Install → pick the target agent.</strong></p><p>From chat, the same thing explicitly:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_mcp_server(agent: &quot;research&quot;, name: &quot;notion&quot;, config: { ... })</span></span></code></pre></div><p>Either way the result is an entry in <code>agents/&lt;name&gt;/.mcp.json</code>. The server is available to <strong>that agent only</strong> — this is the main reason to give a capability its own agent rather than widening PRIME&#39;s toolbelt.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>Many MCP servers need OAuth or an API key.</p><ul><li><strong>API keys</strong> go in the server config, sourced from your secrets store — not pasted into a repo file.</li><li><strong>OAuth servers</strong> need an interactive authorisation once. A server that has never been authorised is unavailable, and a headless or scheduled run cannot complete the flow. Authorise it from an interactive session first.</li></ul><p>Saidi probes configured servers to report which are reachable, which are unauthorised, and which are misconfigured, so a broken server shows up as a status rather than as a mysterious tool failure mid-run.</p><h2 id="install-a-skill" tabindex="-1">Install a skill <a class="header-anchor" href="#install-a-skill" aria-label="Permalink to &quot;Install a skill&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import_skill(agent: &quot;research&quot;, url: &quot;https://.../pricing-scan.md&quot;)</span></span>
<span class="line"><span>add_skill(agent: &quot;research&quot;, name: &quot;competitor-teardown&quot;, content: &quot;...&quot;)</span></span></code></pre></div><p>Skills land in <code>agents/&lt;name&gt;/skills/</code>. A skill is a procedure the agent can invoke by name; it is loaded on demand rather than sitting in the system prompt, so a large library costs nothing until used.</p><h2 id="before-you-install" tabindex="-1">Before you install <a class="header-anchor" href="#before-you-install" aria-label="Permalink to &quot;Before you install&quot;">​</a></h2><ul><li><strong>Read what it can reach.</strong> An MCP server is a capability grant. A server with write access to a production system belongs on a <code>permission: custom</code> agent with a short tool list, not on one with <code>all</code>.</li><li><strong>Prefer the narrowest agent.</strong> If only one specialist needs it, only that specialist should have it.</li><li><strong>Check it after install.</strong> Run the agent read-only on a trivial task and confirm the tool actually resolves before you plan a run around it.</li></ul><h2 id="removing" tabindex="-1">Removing <a class="header-anchor" href="#removing" aria-label="Permalink to &quot;Removing&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>remove_mcp_server(agent: &quot;research&quot;, name: &quot;notion&quot;)</span></span></code></pre></div><p>This edits the agent&#39;s <code>.mcp.json</code>. Removing a server that a saved skill depends on will surface as a tool failure the next time that skill runs — remove both together.</p><p>See also: <a href="./writing-a-custom-agent">Writing a Custom Agent</a> · <a href="/docs/concepts/agents-and-departments">Agents &amp; Departments</a></p>`,23)])])}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
